use std::collections::HashMap;

fn main() {
    let mut stock = HashMap::new();
    stock.insert("apples", 12);
    stock.insert("pears", 5);

    println!("apples: {:?}", stock.get("apples"));
    println!("kiwis: {:?}", stock.get("kiwis"));

    stock.insert("pears", 9);   // replaces the old value
    println!("pears now {}", stock["pears"]);
}

use std::collections::HashMap;

fn main() {
    let text = "the cat and the hat";
    let mut counts = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word).or_insert(0) += 1;
    }
    println!("the: {}", counts["the"]);
    println!("cat: {}", counts["cat"]);
}

use std::collections::HashMap;

fn main() {
    let mut ages = HashMap::new();
    ages.insert("Minh", 31);
    ages.insert("Lan", 28);
    let mut names: Vec<_> = ages.keys().collect();
    names.sort();
    for name in names {
        println!("{name} is {}", ages[name]);
    }
}

